  function renderRecoveryRunStatus(job){
    const panel=$("recovery-run-status");
    if(!panel)return;
    const status=job&&job.status?job.status:"queued";
    const report=job?reportFor(job):null;
    const recovery=report&&report.recovery_monitoring?report.recovery_monitoring:{};
    const dryRunValidated=report&&report.final_status==="dry_run_validated";
    const safeFailure=report&&report.final_status==="safe_failure";
    const recoveryLabel=dryRunValidated?"Dry-run 검증 완료":safeFailure?"안전 중단":recovery.recovery_success===true?"성공":recovery.recovery_success===false?"실패":null;
    const terminal=Boolean(job&&TERMINAL.has(status));
    const visualStatus=dryRunValidated||recoveryLabel==="성공"?"success":recoveryLabel==="실패"||safeFailure?"danger":statusClass(status);
    const title=!job?"실행 대기":terminal&&recoveryLabel?`실험 ${recoveryLabel}`:`실험 ${jobStatusLabel(status)}`;
    let message="시나리오와 실행 모드를 선택한 뒤 실험을 실행하세요.";
    if(job){
      if(status==="queued")message="실험 Job이 실행 대기열에 등록되었습니다.";
      else if(status==="running")message="장애 주입, Evidence 수집, Agent 판단, 안전 검증과 복구 확인을 실행 중입니다.";
      else if(status==="completed"&&dryRunValidated)message="Agent 합의와 안전 명령 검증이 완료되었습니다. Kubernetes 변경과 실제 복구 평가는 수행하지 않았습니다.";
      else if(status==="completed"&&recoveryLabel==="성공")message="복구가 완료되었습니다. 결과 상세에서 Evidence와 Agent Reward를 확인하세요.";
      else if(status==="completed"&&recoveryLabel==="실패")message="실험은 종료되었지만 복구 결과가 실패로 기록되었습니다. 결과 상세에서 원인을 확인하세요.";
      else if(status==="completed")message="실험이 완료되었습니다. 결과 상세에서 실행 결과와 평가를 확인하세요.";
      else if(status==="blocked")message="안전 정책에 의해 실행이 중단되었습니다. 차단 사유를 확인하세요.";
      else if(status==="failed")message=job.error||"실험 중 오류가 발생했습니다. 로그와 이벤트를 확인하세요.";
      else if(status==="cancelled")message="실험이 취소되었습니다.";
      else if(status==="interrupted")message="서버 재시작으로 실험이 중단되었습니다.";
    }
    panel.className=`surface recovery-run-status ${visualStatus}`;
    const icon=$("recovery-run-status-icon");
    if(icon){ icon.className=`recovery-run-status-icon ${visualStatus}`; icon.textContent=visualStatus==="success"?"✓":visualStatus==="danger"?"!":status==="running"?"…":terminal?"—":"○"; }
    text("recovery-run-status-title",title);
    text("recovery-run-status-message",message);
    text("recovery-run-status-id",job&&job.experiment_id?`Experiment ID · ${job.experiment_id}`:"Experiment ID · —");
    const resultButton=$("recovery-view-result");
    if(resultButton)resultButton.hidden=!terminal;
  }

  function renderJob(job){
    state.job=job;
    state.experimentId=job.experiment_id;
    state.running=!TERMINAL.has(job.status);
    renderRecoveryRunStatus(job);
    updateRecoveryPhase(job);
    if(job.request){
      if(state.scenarios[job.request.scenario_id])state.selectedScenario=job.request.scenario_id;
      if(job.request.mode)state.selectedMode=job.request.mode;
      $("controller-select").value=job.request.controller||"deterministic";
      if($("model-input")&&job.request.model)$("model-input").value=job.request.model;
      if($("profile-select"))$("profile-select").value=job.request.protocol_profile||"four-agent-role-veto-v1";
      $("controller-model").hidden=job.request.controller!=="autogen";
      setPressed("scenario-list","button[data-scenario]",state.selectedScenario,(b)=>b.dataset.scenario);
      setPressed("mode-control","button[data-mode]",state.selectedMode,(b)=>b.dataset.mode);
      setPressed("controller-options","button[data-controller]",$("controller-select").value,(b)=>b.dataset.controller);
      if($("overview-scenario-select"))$("overview-scenario-select").value=state.selectedScenario;
      if($("overview-mode-select"))$("overview-mode-select").value=state.selectedMode;
      if($("overview-controller-select"))$("overview-controller-select").value=$("controller-select").value;
    }
    ["header-mode-badge","overview-mode-badge","experiment-mode-badge","selection-runtime-badge"].forEach((id)=>setModeBadge(id,state.selectedMode));
    const report=reportFor(job);
    renderExperimentDirection(job);
    renderOverviewContext(job);
    renderOverviewAgents(report);
    renderOverviewResult(report);
    renderRecoveryCompletionSummary(job);
    renderOverviewStages(job);
    $("run-experiment").disabled=state.running||($("controller-select").value==="autogen"&&!(state.connections.autogen&&state.connections.autogen.ready));
    $("cancel-experiment").disabled=!state.running;
    if(TERMINAL.has(job.status))stopTimer();
    renderDetail(job);
    window.dispatchEvent(new CustomEvent("aiops:job-rendered"));
  }
