  function renderAIOpsLabJob(job){ state.aiopslabJob=job;state.aiopslabJobId=job.job_id;const running=!TERMINAL.has(job.status),result=job.result||{};setBadge("aiopslab-job-status",jobStatusLabel(job.status),statusClass(job.status));$("aiopslab-run").disabled=running||!state.aiopslabRuntimeReady;$("aiopslab-cancel").disabled=!running;$("aiopslab-delete-current").disabled=!TERMINAL.has(job.status);setBadge("aiopslab-runtime-status",running?`${stageLabel(job.current_stage)} · 실행 중`:(state.aiopslabRuntimeReady?"실행 가능":"런타임 미준비"),running?"warning":state.aiopslabRuntimeReady?"success":"warning");text("aiopslab-accuracy",result.accuracy==null?"—":`${(Number(result.accuracy)*100).toFixed(1)}%`);text("aiopslab-ttd",result.average_ttd==null?"—":`${formatNumber(result.average_ttd,3)}s`);text("aiopslab-steps",result.average_steps==null?"—":formatNumber(result.average_steps,2));text("aiopslab-reward",result.average_final_reward==null?"—":formatNumber(result.average_final_reward,3));renderAIOpsLabArtifacts(job.artifact_urls||{});if(job.error)text("aiopslab-error",job.error);if(TERMINAL.has(job.status))closeAIOpsLabEvents(); }
  function addAIOpsLabEvent(event){ state.aiopslabEvents.push(event);text("aiopslab-event-count",`${state.aiopslabEvents.length} events`);const list=$("aiopslab-event-log");if(state.aiopslabEvents.length===1)list.replaceChildren();const li=document.createElement("li");li.textContent=`[${stageLabel(event.stage)}] ${event.message}${event.payload&&event.payload.repetition?` · ${event.payload.repetition}회차`:""}`;list.append(li); }
